    void BuildPalette()
    {
        if(palette==null)return;paletteScenery=Project.Settings.Scenery;palette.SuspendLayout();
        try{
            foreach(Control c in palette.Controls.Cast<Control>().ToArray()){if(c is Button b){var image=b.Image;b.Image=null;image?.Dispose();}palette.Controls.Remove(c);c.Dispose();}
            var entries=DecorationArtwork.Entries(paletteScenery);
            if(!entries.Any(e=>e.Type==activeDecoType&&e.TwoSided==activeDecoTwoSided)&&entries.Count>0){activeDecoType=entries[0].Type;activeDecoTwoSided=entries[0].TwoSided;}
            foreach(var entry in entries){
                var b=new Button{Tag=entry,Image=DecorationArtwork.Palette(paletteScenery,entry.Type,entry.TwoSided),Width=48,Height=48,Margin=new(2),AccessibleName=entry.Name,BackColor=Color.FromArgb(45,45,45),FlatStyle=FlatStyle.Flat};
                hints.SetToolTip(b,UiLanguage.T(entry.Name));
                b.Click+=(_,_)=>{activeDecoType=entry.Type;activeDecoTwoSided=entry.TwoSided;UpdatePaletteSelection();ClassicTool("decorate");};palette.Controls.Add(b);
            }
            LayoutPalette();
            UpdatePaletteSelection();
        }finally{palette.ResumeLayout(true);}
    }
    void UpdatePaletteSelection()
    {
        foreach(var b in palette.Controls.OfType<Button>())if(b.Tag is DecorationArtwork.PaletteItem e){b.FlatAppearance.BorderColor=e.Type==activeDecoType&&e.TwoSided==activeDecoTwoSided?Color.FromArgb(255,159,10):UiTheme.Muted;b.Invalidate();}
        var key=(paletteScenery,activeDecoType,activeDecoTwoSided);
        if(decoPreview!=null&& !Equals(decoPreview.Tag,key)){var previous=decoPreview.Image;decoPreview.Image=DecorationArtwork.Palette(key.paletteScenery,key.activeDecoType,key.activeDecoTwoSided);decoPreview.Tag=key;previous?.Dispose();}
        if(decoName!=null){var variants=DecorationArtwork.Variants(paletteScenery,activeDecoType,activeDecoSide,activeDecoTrack,activeDecoTwoSided);decoName.Text=UiLanguage.T(DecorationArtwork.Name(paletteScenery,activeDecoType))+(activeDecoTwoSided?"":" ("+UiLanguage.T("one side")+")")+(variants.Count>0?"\n"+variants[0].GetProperty("len").GetDouble().ToString("0.0")+" "+UiLanguage.T("m item"):"");}
    }
    IEnumerable<Decoration> SelectedDecorations(){int i=Canvas.SelectedDecoration;return i>=0&&i<Project.Decorations.Count?[Project.Decorations[i]]:[];}
    void PlaceAt(Vec point){if(Preview==null||Ted!=null)return;double best=double.MaxValue,distance=0;for(double d=0;d<Preview.PlanLength;d+=5){double delta=Geometry.Length(Geometry.At(Preview.Points,d).Point,point);if(delta<best){best=delta;distance=d;}}double start=Math.Max(0,distance-5),end=Math.Min(Preview.PlanLength,distance+5);for(double d=start;d<=end;d+=.25){double delta=Geometry.Length(Geometry.At(Preview.Points,d).Point,point);if(delta<best){best=delta;distance=d;}}var (position,angle)=Geometry.At(Preview.Points,distance);Vec deltaPoint=point-position;string side=deltaPoint.X*-Math.Sin(angle)-deltaPoint.Y*Math.Cos(angle)>0?"left":"right";PlaceDecoration(Canvas.SnapDecorations?Math.Round(distance/5)*5:distance,true,side);}
    void PlaceDecoration(double distance,bool commit,string? clickedSide=null){if(Project.Decorations.Count>=TLCPlus.Project.DecorationLimit)return;string side=clickedSide??activeDecoSide;var variants=DecorationArtwork.Variants(Project.Settings.Scenery,activeDecoType,side,activeDecoTrack,activeDecoTwoSided);if(variants.Count==0)return;var v=variants[Random.Shared.Next(variants.Count)];int sideIndex=side=="right"?1:0;if(v.GetProperty("disp")[sideIndex].GetInt32()==0)side=sideIndex==0?"right":"left";Project.Decorations.Add(new(){Uuid=v.GetProperty("uuid").GetUInt64(),Type=activeDecoType,Side=side,Track=activeDecoTrack,Vpos=Math.Clamp(distance,0,Preview?.PlanLength??distance)});Canvas.SelectDecoration(Project.Decorations.Count-1);if(commit)Commit();}
    Button AddIcon(Control parent,string name,string tooltip,Action action){var b=new Button{Width=30,Height=30,BackColor=Bg,FlatStyle=FlatStyle.Flat,Margin=new(1),ForeColor=TextColor,AccessibleName=tooltip,Tag="icon-button",UseVisualStyleBackColor=false};b.FlatAppearance.BorderSize=0;b.FlatAppearance.MouseOverBackColor=Color.FromArgb(60,60,60);string image=Path.Combine(Terrain.AssetsPath,"icons/tools",name+".gif");if(name=="road")b.Image=RoadToolIcon();else if(File.Exists(image)){using var src=Image.FromFile(image);b.Image=new Bitmap(src);}else b.Text=name[..1];b.Click+=(_,_)=>Try(action);hints.SetToolTip(b,tooltip);parent.Controls.Add(b);return b;}
    void BuildFloatingToolbar(){var panel=new Panel{Left=37,Top=37,Width=76,Height=229,BackColor=Bg,BorderStyle=BorderStyle.FixedSingle};int y=4,col=0;void Add(string icon,string tooltip,Action action,string? tool=null){var b=AddIcon(panel,icon,tooltip,action);b.SetBounds(4+col*33,y,30,30);if(tool!=null)iconButtons[tool]=b;if(++col==2){col=0;y+=32;}}void Separator(){if(col!=0){y+=32;col=0;}var line=new Panel{Left=4,Top=y+3,Width=65,Height=1,BackColor=Color.FromArgb(133,133,133)};panel.Controls.Add(line);y+=10;}
        Add("pen","Pen tool",()=>ClassicTool("pen"),"pen");Add("selection","Selection tool",()=>ClassicTool("select"),"select");Add("camber","Camber tool",()=>ClassicTool("camber"),"camber");Add("pan","Panning tool",()=>ClassicTool("pan"),"pan");Add("decorate","Decoration tool",()=>ClassicTool("decorate"),"decorate");Add("road","Road type tool",()=>ClassicTool("road"),"road");Separator();Add("zoom_in","Zoom in",()=>{Canvas.Zoom*=Math.Sqrt(2);Canvas.Invalidate();});Add("zoom_out","Zoom out",()=>{Canvas.Zoom/=Math.Sqrt(2);Canvas.Invalidate();});Separator();Add("reverse","Reverse direction",Reverse);Add("screenshot","Save screenshot",ExportImage);Separator();var sidebar=new Button{Text="Sidebar",Left=4,Top=y,Width=65,Height=28,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(10,132,255),ForeColor=Color.White,Font=new("Segoe UI",8)};sidebar.FlatAppearance.BorderSize=0;sidebar.Click+=(_,_)=>mainSplit.Panel1Collapsed=!mainSplit.Panel1Collapsed;panel.Controls.Add(sidebar);panel.Height=sidebar.Bottom+5;Canvas.Controls.Add(panel);panel.BringToFront();ClassicTool("pan");}
    static Bitmap RoadToolIcon()
    {
        var image=new Bitmap(24,24);using var g=Graphics.FromImage(image);g.SmoothingMode=SmoothingMode.AntiAlias;
        using var edge=new Pen(UiTheme.Text,1.2f);g.DrawBezier(edge,3,21,6,11,15,14,19,3);g.DrawBezier(edge,9,23,12,13,21,16,23,5);
        using var center=new Pen(UiTheme.Text,1){DashStyle=DashStyle.Dash};g.DrawBezier(center,6,22,9,12,18,15,21,4);return image;
    }
    void RefreshToolButtons(){string active=Canvas.Tool=="road-erase"?"road":Canvas.Tool;foreach(var pair in iconButtons)pair.Value.BackColor=pair.Key==active?UiTheme.Button:UiTheme.Panel;}
    void ClassicTool(string tool){SetTool(tool);RefreshToolButtons();if(tool is "decorate" or "road" or "road-erase"){if(tool!="decorate")mainSplit.Panel1Collapsed=false;ShowPage(3);if(tool=="decorate")classicPages[3].AutoScrollPosition=Point.Empty;else RevealRoadControls();}}
    void RevealRoadControls()
    {
        var page=classicPages[3];page.AutoScrollMinSize=Size.Empty;page.PerformLayout();
        var footer=page.Controls[^1];
        page.AutoScrollMinSize=new Size(0,footer.Bottom-page.AutoScrollPosition.Y+page.Padding.Bottom);
        page.ScrollControlIntoView(footer);
    }
    void ToolGesture(string tool,Vec from,Vec to){if(Ted!=null||Project.Nodes.Count==0)return;var points=(Canvas.Selected.Count>0?Canvas.Selected.Select(i=>Project.Nodes[i]):Project.Nodes).ToList();Vec center=new(points.Average(n=>n.X),points.Average(n=>n.Y));if(tool=="rotate"){double a=Geometry.Angle(center,to)-Geometry.Angle(center,from);foreach(var n in points){Vec v=n.XY-center;n.XY=center+new Vec(v.X*Math.Cos(a)+v.Y*Math.Sin(a),-v.X*Math.Sin(a)+v.Y*Math.Cos(a));}}else if(tool=="scale"){double before=Geometry.Length(from,center),after=Geometry.Length(to,center),f=before<1?1:after/before;foreach(var n in points){n.XY=center+(n.XY-center)*f;n.Radius*=f;}}UpdatePreview();}
    void EditNode(){if(Ted!=null||Canvas.Tool is "decorate" or "road" or "road-erase"||Canvas.Selected.Count==0)return;Canvas.FinishGesture();using var dialog=new NodePropertiesDialog(Project.Nodes[Canvas.Selected.First()],Canvas.Selected.Count);if(dialog.ShowDialog(this)==DialogResult.OK){dialog.ApplyTo(Canvas.Selected.Select(i=>Project.Nodes[i]));Commit();}}
    void ImportReferenceTed(){using var d=new OpenFileDialog{Filter="GT6 TED|*.ted"};if(d.ShowDialog()==DialogResult.OK){Canvas.ReferenceCourse=TedDocument.Read(File.ReadAllBytes(d.FileName)).Course;Canvas.Invalidate();}}
    void RefreshPythonControls(){RefreshRoadTypeControls();RefreshRoadTypeHint();bool prior=binding;binding=true;foreach(var bind in bindings)bind();binding=prior;if(palette!=null&&paletteScenery!=Project.Settings.Scenery)BuildPalette();if(decoInfo!=null)decoInfo.Text=string.Format(UiLanguage.T("{0} / {1} decorations"),Project.Decorations.Count,TLCPlus.Project.DecorationLimit);RefreshCanvasStats(Preview??Canvas.Course);}
